/bin/bash -lc "cd [workspace path] && python3 -c \"
import numpy as np
d = np.load('source_pixels.npz')['rgb'].astype(int)
for i in [0,5,9,10,15,30,50,70,95]:
    f=d[i]; R,G,B=f[...,0],f[...,1],f[...,2]
    red=(R>110)&(R-G>45)&(R-B>45)
    ys,xs=np.where(red)
    if len(xs): print(i,'red n=',len(xs),'bbox x',xs.min(),xs.max(),'y',ys.min(),ys.max())
    else: print(i,'no red')
\""
